"""Queue types for voice event composition."""

from __future__ import annotations

from rasa.core.channels.conversation_queue.queue import InMemoryConversationQueue
from rasa.core.voice.event_composition.events import CompositeEvent
from rasa.core.voice.event_composition.events.input_events import InputEvent
from rasa.tracing import voice as voice_tracing


class RawEventQueue(InMemoryConversationQueue[InputEvent]):
    """Queue carrying raw voice events produced by the channel."""


class InteractionEventQueue(InMemoryConversationQueue[CompositeEvent]):
    """FIFO queue carrying composed interaction events to the processor."""

    def __init__(
        self, conversation_id: str, input_channel: str, maxsize: int = 50
    ) -> None:
        """Create a chronological interaction-event queue."""
        super().__init__(conversation_id, input_channel, maxsize)

    @voice_tracing.traced_interaction_event_enqueue
    async def put(self, event: CompositeEvent) -> None:
        """Add a composed interaction event to the queue."""
        await super().put(event)
